style.css:
@-moz-document domain("divar.ir"), domain("www.divar.ir") {
/*
   * Divar's UI is built almost entirely from CSS custom properties (a Kenar/KT
   * design system, ~260 tokens on :root). Tokens come in two shapes:
   *   - hex/keyword form, used directly:           --surface-primary: #fff
   *   - RGB-triplet form, used as rgb(var(--x)):   --surface-neutral-weaker: 255,255,255
   * So every remap below is provided in the form Divar actually consumes.
   *
   * Strategy (RTL-safe — colours only, no layout changes):
   *   - Remap SURFACE tokens (white/grey) -> dark elevated surfaces.
   *   - Remap CONTENT tokens (near-black greys) -> light foregrounds.
   *   - Flip the black-with-alpha text tokens (rgba(0,0,0,X)) to white-with-alpha
   *     so muted metadata (price/location/post-time/spec rows) stays legible.
   *   - Preserve semantic colours (positive/negative/warning/informative) but
   *     pull their light pastel SURFACES down to dark tints.
   *   - Keep Divar's brand red identity, refined so it sits well on near-black.
   */
  :root {
    color-scheme: dark;

    /* ---- Surfaces: white/grey page + card backgrounds -> dark ---- */
    --surface-primary: #161b22;
    --surface-secondary: #1c2128;
    --surface-tertiary: #262c33;
    --white: #161b22;
    --white-primary: #161b22;
    /* Painted by the sticky header's scrollbar-gutter `::before` (a 15px strip
       beside the bar, visible whenever a nav dimmer is open and the browser
       draws a classic scrollbar) and by `.kt-select__control`. Left unmapped it
       stayed a 98%-white sliver welded to the dark header. */
    --white-nav: #0d1117;
    --static-white: #ffffff; /* genuine static white (e.g. on-image chips) kept */
    --gray-50: #14181d;
    --gray-100: #161b22;
    --gray-200: #1c2128;
    --gray-400: #6e7681;
    --gray-750: #aeb7c0;
    --gray-800: #c4cdd6;
    --gray-850: #d0d7de;
    --gray-900: #e6edf3;
    --gray: #e6edf3;

    /* RGB-triplet surfaces (consumed via rgb(var(--x))) */
    --surface-neutral-weaker: 22, 27, 34;   /* was 255,255,255 */
    --surface-neutral-weak: 28, 33, 40;     /* was 244,244,245 */
    --surface-neutral-default: 38, 44, 51;  /* was 228,228,231 */
    --surface-neutral-strong: 72, 79, 88;   /* was 195,195,201 */
    --surface-neutral-stronger: 110, 118, 129;
    --surface-neutral-on-color: 22, 27, 34;

    /* ---- Content / text: near-black greys -> light foregrounds ---- */
    --content-primary: #e6edf3;
    --content-secondary: #aeb7c0;
    --content-tertiary: #8b949e;
    --content-quaternary: #6e7681;
    --black: #e6edf3;
    --black-tooltip: #2c333b;

    /* RGB-triplet content tokens */
    --content-neutral-stronger: 230, 237, 243; /* was 36,36,40 */
    --content-neutral-strong: 196, 205, 214;   /* was 82,82,91 */
    --content-neutral-default: 154, 164, 174;  /* was 113,113,122 */
    --content-neutral-weak: 139, 148, 158;     /* was 161,161,170 */
    --content-neutral-weaker: 110, 118, 129;   /* was 195,195,201 */
    --content-neutral-on-color: 22, 27, 34;
    --content-inverted-primary: #14181d;
    --content-inverted-default: 110, 118, 129;
    --content-inverted-on-color: 230, 237, 243;

    /* Divar now ships its OWN dark palette, applied as <html data-theme="dark">
       when the OS asks for dark. Under it a handful of tokens flip to LIGHT
       values (an "inverted" surface is light once the page is already dark).
       Every rule in this file is authored against the LIGHT-mode semantics, so
       pin those tokens back — otherwise e.g. the on-photo `.kt-tag--dark` chip
       becomes a white pill and our light label on it turns invisible. On a
       light OS these values are already the site's own, so nothing changes. */
    --surface-inverted-primary: #2c2c30;
    --surface-inverted-secondary: #52525b;
    --surface-inverted-strong: 36, 36, 40;
    --surface-inverted-stronger: 24, 24, 27;
    --surface-inverted-weak: 82, 82, 91;
    --surface-inverted-weaker: 113, 113, 122;
    --content-inverted-stronger: 195, 195, 201;

    /* Scrims behind modals/galleries: dark-mode flips these to white veils */
    --surface-dimmer-primary: rgba(0, 0, 0, 0.32);
    --surface-dimmer-secondary: rgba(0, 0, 0, 0.64);

    /* Black-with-alpha text tokens -> white-with-alpha (muted metadata) */
    --black-primary: rgba(230, 237, 243, 0.92);
    --black-secondary: rgba(230, 237, 243, 0.66);
    /* 0.45 (the site's own hint alpha, fine as black-on-white) only reaches
       ~3.9:1 as white-on-dark — it carries real label text (select values,
       field suffixes, result counts), so lift it until it clears 4.5:1. */
    --black-hint: rgba(230, 237, 243, 0.62);
    --black-divider: rgba(230, 237, 243, 0.12);
    --black-light-100: rgba(230, 237, 243, 0.04);
    --black-light-200: rgba(230, 237, 243, 0.08);
    --black-medium-100: rgba(230, 237, 243, 0.16);
    --black-medium-200: rgba(230, 237, 243, 0.24);
    --black-dark-100: rgba(230, 237, 243, 0.48);
    --black-hover: rgba(230, 237, 243, 0.12);
    --black-press: rgba(230, 237, 243, 0.16);

    /* ---- Borders / dividers -> dark (kills bright light lines) ---- */
    --border-primary: #2d333b;
    --border-secondary: #2d333b;
    --border-tertiary: #262c33;
    --border-neutral-default: 45, 51, 59;
    --border-neutral-weak: 38, 44, 51;
    --border-neutral-weaker: 33, 38, 45;
    --border-neutral-strong: 72, 79, 88;
    --border-neutral-stronger: 110, 118, 129;
    --border-inverted-primary: #2d333b;
    --dimmer-light: rgba(0, 0, 0, 0.32);
    --dimmer-dark: rgba(0, 0, 0, 0.5);

    /* ---- Brand red: keep identity, refine tone for dark ----
       `--brand` has two jobs: it is the LINK/label red AND the fill of every
       primary button. On a near-black page the text job needs it light
       (#e86369 → 5.0:1 even on the elevated #1c2128 modal surface, where the
       old #e2575c dipped to 4.4:1); the fill job then leaves white CTA labels
       at only 3.5:1, where Divar's own #a62626 gave 7.2:1. Keep the token light
       for text and darken the filled SURFACES separately (see
       `.kt-button--primary` below) — `--brand-hover`/`--brand-press` also
       colour text, so they stay light too. */
    --brand: #e86369;
    --brand-primary: #e86369;
    --brand-hover: #ec6b6f;
    --brand-press: #d34449;
    --surface-brand-primary: #cf4046;
    --surface-brand-secondary: #6e2b30;
    --surface-brand-tertiary: #3a2023;
    --surface-brand-quaternary: #2a191b;
    /* Divar reads a whole family of tokens ONLY as `rgb(var(--x))`. Handing one
       a hex is not a no-op: `rgb(#3a2023)` is invalid at computed-value time, so
       the property resolves to `unset` — a background falls to `transparent`,
       and `color` / `border-color`, being inherited, fall to the surrounding
       white. Every token below therefore has to be a bare RGB triplet.
       `-weak` (the dotted slider range) follows Divar's own dark-mode value so
       the dashes stay visible; `-strong` fills the slider range and plate flag. */
    --surface-brand-weak: 116, 28, 28;
    --surface-brand-weaker: #2a191b;
    --surface-brand-weakest: #1f1719;
    --surface-brand-strong: 207, 64, 70;
    --surface-brand-stronger: 207, 64, 70;
    --surface-brand-strongest: 189, 54, 60;
    --surface-brand-default: 207, 64, 70;
    --content-brand-primary: #e86369;
    --content-brand-secondary: #ec6b6f;
    /* Also `rgb(var(...))`-only: the bookmarked-bookmark icon, the cost-card
       price, the hashed `.branded-*` / `.brand-color-*` labels, checked
       option-selector rows, and the 2px border of a checked cost card. As hexes
       these lost their red altogether and inherited the page's light text
       colour — a bookmarked post looked identical to an unbookmarked one. */
    --content-brand-strong: 232, 99, 105;
    --content-brand-stronger: 236, 107, 111;
    --content-brand-default: 232, 99, 105;
    --content-brand-weak: 224, 130, 130;
    --content-brand-weaker: 90, 47, 49;
    --content-brand-inverted: #e86369;
    --border-brand-primary: #e2575c;
    --border-brand-secondary: #c2484c;
    --border-brand-strong: 226, 87, 92;
    --border-brand-default: #b54e51;
    --border-brand-weak: #6e2b30;
    --border-brand-weaker: #3a2023;
    --border-brand-quaternary: #3a2023;
    --brand-light-100: rgba(226, 87, 92, 0.06);
    --brand-light-200: rgba(226, 87, 92, 0.1);
    --brand-medium-100: rgba(226, 87, 92, 0.16);
    --brand-medium-200: rgba(226, 87, 92, 0.24);
    --brand-divider: rgba(226, 87, 92, 0.16);
    --brand-hint: rgba(226, 87, 92, 0.32);
    --surface-dimmer-brand-primary: rgba(226, 87, 92, 0.18);
    --surface-dimmer-brand-secondary: rgba(226, 87, 92, 0.32);

    /* ---- Links / informative blue -> brighter for dark ---- */
    --tertiary: #5fb0e6;
    --blue-primary: #5fb0e6;
    --blue-800: #5fb0e6;
    --blue-outline: #5fb0e6;
    --content-informative-primary: #5fb0e6;
    --content-informative-default: #5fb0e6;
    --content-informative-strong: #79c0ff;
    --content-informative-secondary: #79c0ff;
    --content-informative-stronger: 121, 192, 255;
    --surface-informative-primary: #2c6fb5;
    /* `rgb(var(...))`-only — as a hex it made `.kt-note-card__container`'s
       background invalid at computed-value time, dropping the card's tint. */
    --surface-informative-weak: 22, 34, 46;
    --surface-informative-weaker: #131c26;
    --surface-informative-default: 30, 45, 60;
    --message: #11202b;
    --message-primary: #11202b;
    --message-secondary: #16222e;

    /* ---- Positive / negative / warning: keep hue, dark surfaces ----
       The `-strong`/`-stronger` variants are near-black ink meant for pale
       status pills; on our darkened status surfaces they read dark-on-dark. */
    --content-positive-primary: #3fb950;
    --content-positive-secondary: #57c463;
    --content-positive-strong: 63, 185, 80;
    --content-positive-stronger: 87, 196, 99;
    --content-negative-stronger: 244, 133, 133;
    /* Divar still carries a legacy status trio next to the semantic scales.
       Unmapped, `--success-primary` (#2e7d32) and `--warning` (#e65100) sit at
       3.7:1 / 3.4:1 as TEXT on our cards — they colour the price-up / price-down
       marks (`.kt-price-row__change--increased` / `--decreased`) and the required
       -field asterisk — and as FILLS (toast, thumbnail caption bar, status pill)
       they pair a saturated dark green/orange/red with the near-black `--white`
       label, i.e. dark-on-dark. Lifting the trio fixes both jobs at once. */
    --success-primary: #3fb950;
    --success-secondary: #57c463;
    --error: #f26464;
    --warning: #e0934a;
    --surface-positive-primary: #1d7c4d;
    --surface-positive-weak: #14241b;
    /* `-weaker` on both scales is read ONLY as `rgb(var(...))`, so a hex made it
       invalid at computed-value time: `.kt-info-box--positive` /
       `.kt-info-box--error` lost their tint to `transparent` entirely. */
    --surface-positive-weaker: 17, 29, 23;
    --surface-positive-default: 18, 36, 27;
    --content-negative-primary: #f26464;
    --content-negative-secondary: #f48585;
    --surface-negative-primary: #c53434;
    --surface-negative-weak: #2a1719;
    --surface-negative-weaker: 33, 20, 23;
    --surface-negative-default: 42, 23, 25;
    --content-warning-primary: #e0934a;
    --content-warning-secondary: #eaa869;
    --surface-warning-primary: #e68f38;
    --surface-warning-weak: #2a2015;
    --surface-warning-weaker: #211a12;
    --surface-warning-default: 42, 32, 21;
    /* A plain hex token, so it survives: unmapped it left `.kt-info-box--warning`
       (the pre-deal fraud warning) a `#fceae0` peach panel carrying our light
       `--black-primary` body text. */
    --semantic-warning-hint: #2a2015;
    --surface-accent-primary: #ffb200;
    --surface-accent-quaternary: #2a2415;
  }

  /* Page backdrop behind the app */
  html,
  body {
    background-color: #0d1117 !important;
  }

  /* Sticky nav / top bar were near-opaque white via --white-nav */
  [class*="nav-bar"],
  .kt-navigation-bar,
  header[class*="nav"] {
    background-color: #0d1117 !important;
  }

  /* ---- Floating surfaces MUST stay opaque (no card bleed-through) ---- */
  .kt-modal,
  .kt-new-modal,
  .kt-new-modal__footer,
  .kt-new-modal__header,
  [class*="modal"],
  [class*="dropdown"],
  [class*="popover"],
  [class*="menu__content"],
  [class*="autocomplete"],
  [class*="bottom-sheet"],
  [class*="overlay-content"],
  .kt-select__options,
  .kt-toast,
  .kt-snackbar,
  .kt-rich-tooltip,
  .react-tooltip,
  [role="tooltip"] {
    background-color: #1c2128 !important;
  }

  /* `[class*="dropdown"]` above is deliberately loose (the panels carry hashed
     classes like `dropdown-dc2a5`), but it also catches the dropdown BUTTON's
     little chevron `<i class="… kt-dropdown-button__arrow-icon">`, painting an
     opaque square behind the glyph. Icons never want a panel background. */
  i[class*="dropdown"] {
    background-color: transparent !important;
  }

  /* `[class*="bottom-sheet"]` has the same problem: it also matches the sheet's
     48×4 drag handle, painting it the sheet's own colour so the grab affordance
     disappears. It's a translucent pill, not a panel — give it back its tint. */
  .kt-bottom-sheet__drag-handler {
    background-color: rgba(230, 237, 243, 0.16) !important;
  }

  /* KT rich tooltip (e.g. the "recently-seen" eye-badge popover on map/list cards
     and the city-input / map draw-control onboarding hints) is a react-tooltip that
     hardcodes a near-white surface (#f9fafb). The bubble is re-darkened above; its
     little pointer arrow is a separate element that keeps the same light fill, so
     dark it too so the pointer matches the bubble. */
  .react-tooltip-arrow {
    background-color: #1c2128 !important;
  }
  /* The rich-tooltip TEXT node (.kt-rich-tooltip__text) hardcodes a near-black
     content colour (#242428) that read fine on the original light bubble but is
     dark-on-dark once the bubble is darkened — invisible. It's hover/onboarding
     only, so a plain element-bg scan never sees it. Force a light label. */
  .kt-rich-tooltip__content,
  .kt-rich-tooltip__text,
  .react-tooltip {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }

  /* Soften any remaining bright/default borders into the dark palette */
  *,
  *::before,
  *::after {
    border-color: #2d333b;
  }

  /* Inline white surface backgrounds set via style attribute */
  [style*="background-color: rgb(255, 255, 255)"],
  [style*="background-color:#fff"],
  [style*="background: rgb(255, 255, 255)"],
  [style*="background:#fff"] {
    background-color: #161b22 !important;
  }

  /* Form fields: dark input, legible muted placeholder, bright typed value */
  input,
  textarea,
  select,
  .kt-textfield__input,
  .kt-nav-text-field__input {
    background-color: #14181d !important;
    color: #e6edf3 !important;
    border-color: #2d333b;
  }
  input::placeholder,
  textarea::placeholder,
  .kt-textfield__input::placeholder,
  .kt-nav-text-field__input::placeholder {
    color: #8b949e !important;
    opacity: 1;
  }
  /* Ghost / additional-value placeholder spans some KT fields render */
  .kt-textfield__input--empty,
  [class*="ghost"],
  [class*="placeholder"] {
    color: #8b949e !important;
  }

  /* Primary "post ad" header CTA: KT primary nav button has no background of its
     own here, so it inherits the dark header and its on-color label token renders
     near-black (dark-on-dark, near-invisible). Give it the brand red surface with
     a light label so the site's most prominent affordance reads clearly. */
  button.kt-button--primary.kt-nav-button,
  a.kt-button--primary.kt-nav-button {
    background-color: #cf4046 !important;
    border-color: #cf4046 !important;
  }
  button.kt-button--primary.kt-nav-button:hover,
  a.kt-button--primary.kt-nav-button:hover {
    background-color: #bd363c !important;
    border-color: #bd363c !important;
  }
  button.kt-button--primary.kt-nav-button .kt-text-truncate,
  button.kt-button--primary.kt-nav-button span,
  a.kt-button--primary.kt-nav-button .kt-text-truncate,
  a.kt-button--primary.kt-nav-button span {
    color: #ffffff !important;
  }

  /* Every filled primary (brand-red) button — e.g. the post-detail "اطلاعات تماس"
     contact CTA, and the brand-red extended FAB ("بستن نقشه" close-map control on
     the map listing) — takes its label from an on-color token we remapped to
     near-black for neutral surfaces, so the label renders dark-on-red. Force a
     white label so the red CTA reads with full contrast. (FAB labels are white on
     either a red or a dark elevated surface, so this is safe across FAB variants.) */
  .kt-button--primary,
  .kt-button--primary .kt-text-truncate,
  .kt-button--primary span,
  .kt-button--primary i,
  .kt-fab-button,
  .kt-fab-button span,
  .kt-fab-button i {
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }

  /* …and the fill those white labels sit on. `--brand` stays light because it
     doubles as the link/label red, so the FILLED brand BUTTONS are darkened
     here instead: #cf4046 puts a white label at 4.7:1 (the light token gave
     3.5:1). Deliberately buttons only — `.kt-chip--primary` also reads
     `var(--brand)` as a fill, but the removable city chip pairs it with
     `--outlined` and expects a 6%-alpha tint behind brand-red text, so filling
     it here would paint red-on-red. Ghost/outlined primaries stay transparent. */
  .kt-button.kt-button--primary,
  .kt-dropdown-button.kt-dropdown-button--primary,
  .kt-fab-button {
    background-color: #cf4046 !important;
  }
  .kt-button.kt-button--primary:hover,
  .kt-button.kt-button--primary:focus,
  .kt-dropdown-button.kt-dropdown-button--primary:hover,
  .kt-fab-button:hover,
  .kt-fab-button:focus {
    background-color: #bd363c !important;
  }
  .kt-button.kt-button--primary:active,
  .kt-fab-button:active {
    background-color: #a92f34 !important;
  }
  /* Every FAB — not just `--primary` — takes `var(--brand)` as its fill (the
     base `.kt-fab-button` rule does), so the extended "بستن نقشه" close-map
     control on the map listing carried our light text-tuned red and put its
     white label at 3.3:1 (3.1:1 on hover). Darkened above with the other filled
     brand surfaces. Ghost FABs are transparent and keep their own label rules. */
  .kt-button--inlined.kt-button--primary,
  .kt-button--outlined.kt-button--primary,
  .kt-fab-button--inlined,
  .kt-fab-button--outlined,
  .kt-fab-button--inlined:hover,
  .kt-fab-button--outlined:hover {
    background-color: transparent !important;
  }

  /* Disabled buttons: KT paints them with `--gray-100` + the `--black-hint`
     label. Our blanket white label on `.kt-button--primary` above overrides that
     hint, so a disabled CTA (e.g. "تأیید" in the city picker before a city is
     picked) renders a full-strength white label and reads as enabled. Restore a
     muted label on a slightly-raised surface so the state stays legible. The
     selectors outweigh the filled-brand rules above, incl. their hover state. */
  .kt-button:disabled,
  .kt-button.kt-button--disabled,
  .kt-button.kt-button--primary.kt-button--disabled,
  .kt-button.kt-button--primary.kt-button--disabled:hover,
  .kt-button.kt-button--primary:disabled,
  .kt-button.kt-button--primary:disabled:hover,
  .kt-fab-button:disabled,
  .kt-fab-button:disabled:hover,
  .kt-fab-button.kt-fab-button--disabled,
  .kt-fab-button.kt-fab-button--disabled:hover {
    background-color: #21262d !important;
    border-color: #21262d !important;
  }
  .kt-button:disabled,
  .kt-button:disabled span,
  .kt-button:disabled i,
  .kt-button--disabled,
  .kt-button--disabled span,
  .kt-button--disabled i,
  .kt-button--primary.kt-button--disabled,
  .kt-button--primary.kt-button--disabled .kt-text-truncate,
  .kt-button--primary.kt-button--disabled span,
  .kt-button--primary.kt-button--disabled i,
  .kt-fab-button:disabled,
  .kt-fab-button:disabled span,
  .kt-fab-button:disabled i,
  .kt-fab-button.kt-fab-button--disabled,
  .kt-fab-button.kt-fab-button--disabled span,
  .kt-fab-button.kt-fab-button--disabled i {
    color: rgba(230, 237, 243, 0.38) !important;
    -webkit-text-fill-color: rgba(230, 237, 243, 0.38) !important;
  }

  /* ---- On-photo carousel chrome ----
     The gallery's scrims and controls are painted from the black-with-alpha
     tokens we flip to white-with-alpha (those tokens also carry muted TEXT, so
     the flip has to stay). Over photographs the flipped values become bleaching
     white veils: unselected thumbnails wash out to near-white, and the arrow /
     close discs invert into light discs with a dark glyph. Restore true black
     scrims and white glyphs on the carousel only. */
  /* The tile UNDER each thumbnail photo (`--black-hint`, a dark placeholder
     natively) — masked on inactive thumbs by the button overlay above, but bare
     on the active one, so it flashes a bright square while the photo loads. */
  .kt-base-carousel__thumbnail {
    background-color: rgba(0, 0, 0, 0.32) !important;
  }
  .kt-base-carousel__thumbnail-button {
    background-color: rgba(0, 0, 0, 0.55) !important;
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }
  .kt-base-carousel__thumbnail-button--active {
    background-color: transparent !important;
  }
  .kt-base-carousel__slide-loading-overlay {
    background-color: rgba(0, 0, 0, 0.32) !important;
  }
  .kt-base-carousel__control-icon {
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
    text-shadow: 0 0 4px rgba(0, 0, 0, 0.65) !important;
  }
  /* Only the full-screen gallery variant carries a disc behind the chevron —
     the inline post carousel draws a bare glyph, so keep its background clear. */
  .kt-gallery-view__dimmer .kt-base-carousel__control-icon,
  .kt-dimmer__close {
    background-color: rgba(0, 0, 0, 0.45) !important;
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }

  /* The play/pause disc that floats over a video slide (`.kt-media-button
     --is-overlay`, on the post carousel and on card thumbnails) is painted from
     the same black-with-alpha tokens: `--black-hint` for the disc, `--white` for
     the glyph and the progress ring. Flipped, it inverts into a near-white disc
     with a near-black arrow sitting on the photo. Restore the dark disc. */
  .kt-media-button--is-overlay {
    background-color: rgba(0, 0, 0, 0.45) !important;
  }
  .kt-media-button--is-overlay:hover,
  .kt-media-button--is-overlay:focus {
    background-color: rgba(0, 0, 0, 0.62) !important;
  }
  .kt-media-button--is-overlay,
  .kt-media-button--is-overlay i,
  .kt-media-button--is-overlay svg {
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
    fill: #ffffff !important;
  }
  .kt-media-button--is-overlay .kt-media-button__progress-circle {
    stroke: #ffffff !important;
  }

  /* The toast takes its surface from `--gray-800` and its label from `--white`.
     Both flip, so it would be a light toast with dark text — but the opaque
     floating-surface rule above re-darkens the surface only, leaving near-black
     text on a near-black toast. Give the label back its white. */
  .kt-snackbar {
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }

  /* A few action affordances hardcode a mid blue (#2385f2) that dips just under
     4.5:1 on the dark cards — brighten to the theme link blue. */
  [style*="color: rgb(35, 133, 242)"],
  [style*="color:#2385f2"] {
    color: #5fb0e6 !important;
  }
  .kt-icon-share-o,
  .kt-icon-added-o,
  .kt-icon-add-o,
  [class*="modal__add"] {
    color: #5fb0e6 !important;
  }

  /* The "photo count" overlay chip on gallery images (kt-tag--dark, e.g. the
     "۵" counter on the post-detail carousel) is a dark chip (#2c2c30, pinned
     above) that overlays photos, so its label/icon take the inverted-content
     token we remapped to near-black (#14181d) — dark-on-dark, nearly invisible.
     Force a light label + icon. Scoped to the --dark variant so other tag tones
     keep their token-driven colours. */
  .kt-tag--dark,
  .kt-tag--dark .kt-tag__text,
  .kt-tag--dark i,
  .kt-tag--dark svg {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
    fill: #e6edf3 !important;
  }

  /* Its sibling `.kt-tag--overlay` (the "پله"/photo-count badge pinned to card
     thumbnails) draws its scrim from `--black-secondary` and its label from
     `--white` — both of which we flip for text/surfaces elsewhere, turning the
     badge into a bright white pill sitting on the photo. Divar's own dark mode
     paints it rgba(0,0,0,0.7); match that so the badge stays a dark scrim. */
  .kt-tag--overlay {
    background-color: rgba(0, 0, 0, 0.7) !important;
  }
  .kt-tag--overlay,
  .kt-tag--overlay .kt-tag__text,
  .kt-tag--overlay i,
  .kt-tag--overlay svg {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
    fill: #e6edf3 !important;
  }

  /* Keep media true to colour — never tint images/video */
  img,
  video,
  picture,
  canvas {
    background-color: transparent !important;
  }

  /* ---- Mapbox GL basemap ----
     Divar's Mapbox GL map (the large left-hand slab on the map-search view) now
     honours `color-scheme: dark` and renders a NATIVE dark basemap on its own
     <canvas> — dark land, blue roads, green parks, red price-cluster pins. So we
     must NOT touch it: an `invert()` filter would flip that already-dark map back
     to a bright light slab. Leave the GL canvas alone. (The post-detail STATIC
     raster map below is a different element that is still served light, so it
     still needs the filter.) */

  /* Post-detail location map is NOT the Mapbox canvas — it's a static raster PNG
     served from mapimage.divarcdn.com, so it stays a bright light slab on the dark
     post page. Apply the same basemap treatment; invert+hue-rotate(180) keeps the
     baked-in red location circle reddish while flipping the pale land to dark. */
  img[src*="mapimage"] {
    filter: invert(0.92) hue-rotate(180deg) brightness(0.9) contrast(0.9) !important;
  }
}
